void *tree_sitter_nx_external_scanner_create(void);
void tree_sitter_nx_external_scanner_destroy(void *);
bool tree_sitter_nx_external_scanner_scan(void *, TSLexer *, const bool *);
unsigned tree_sitter_nx_external_scanner_serialize(void *, char *);
void tree_sitter_nx_external_scanner_deserialize(void *, const char *, unsigned);

